def env_bool(value, default=False):
    if value is None:
        return default
    if isinstance(value, str):
        lowered = value.strip().lower()
        if lowered in ('false', '0', 'no', 'off'):
            return False
        if lowered in ('true', '1', 'yes', 'on'):
            return True
    return bool(value)

def load(env):
    return {'debug': env_bool(env.get('APP_DEBUG'), False)}
